def transforms(S):
 out=[]
 for flip in [False,True]:
  for rot in range(4):
   coords=[]
   for r,c in S:
    if flip: c=-c
    for _ in range(rot): r,c=c,-r
    coords.append((r,c))
   mr=min(r for r,c in coords); mc=min(c for r,c in coords)
   out.append({(r-mr,c-mc) for r,c in coords})
 return list(dict.fromkeys(map(frozenset,out)))
